import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve, sep } from 'node:path';

import { log } from './log.js';

import type { Config } from './config.js';

const CONFIG_PATH = join(process.cwd(), 'bd-css.config.js');

/**
 * Loads the `bd-css.config.js`, `root.css`, and `main.css` files.
 */
export const loadConfig = async () => {
	if (!existsSync(CONFIG_PATH)) {
		log.error([
			`Cannot find ${log.code('bd-css.config.js')} in the root of your directory.`,
			'',
			`If you do have a config file, make sure to include ${log.code('type": "module', '"')} in your ${log.code('package.json')} file.`
		]);
	}

	const local = (await import(join(process.cwd(), 'bd-css.config.js'))).default as Config;

	const config = {
		meta: local.meta,
		root: local.root || 'src/root.css',
		main: local.main || 'src/main.css',
		betterdiscord: {
			themeFolder: getDataFolder('BetterDiscord'),
			...local.betterdiscord
		},
		prettyfluxer: {
			themeFolder: getDataFolder('PrettyFluxer'),
			...local.prettyfluxer
		},
		vencord: { themeFolder: getDataFolder('Vencord'), dev: false, ...local.vencord },
		addons: local.addons || [],
		github: local.github || {
			profile: local.meta.author,
			repo: local.meta.name
		},
		static: local.static || false
	} satisfies Config;

	return config;
};

/**
 * Get the client mod datafolder.
 * @param mod The directory to search for.
 */
export const getDataFolder = (mod: 'BetterDiscord' | 'Vencord' | 'PrettyFluxer') => {
	// Fix GitHub from running this and simply return the relative `dist` folder.
	if (process.argv[2] === 'build') return 'dist';

	let folder: string = '';

	if (process.platform === 'win32') {
		folder = resolve(process.env.APPDATA!, mod, 'themes');
	} else if (process.platform === 'darwin') {
		folder = resolve(process.env.HOME!, 'Library', 'Application Support', mod, 'themes');
	} else if (process.platform === 'linux') {
		const linuxPaths = [resolve(process.env.HOME!, '.local', 'share', mod, 'themes'), resolve(process.env.HOME!, '.config', 'InFlux', 'Themes'), resolve(process.env.HOME!, '.config', mod, 'Themes')];
		for (let i = 0; i < linuxPaths.length; i++) {
			const el = linuxPaths[i];
			if (existsSync(el)) {
				folder = el;
				break;
			}
		}
	} else throw new Error('Cannot determin your OS.');

	if (folder[0] === '~') folder = process.env.HOME! + folder.substring(1);

	return folder;
};

/**
 * Generate a CSS import based on the `bd-css.config.js` file.
 * @param config The config object.
 * @param name The name of the file.
 */
export const generateImport = (config: Config) => {
	const repo = config.github?.repo || config.meta.name;
	const profile = config.github?.profile || config.meta.author;

	return `@import url('https://nexus-themes.github.io/${repo.replace(/ /g, '')}/${config.meta.name.replace(/ /g, '')}.css');`;
};

/**
 * Generates the root css.
 * @param config The local config object
 */
export const generateRootCSS = (config: Required<Config>, opts: { includeExternalImport: boolean }) => {
	let root: string = generateMeta(config.meta);
	if (opts.includeExternalImport) root += generateImport(config) + '\n\n';
	root += readFileSync(join(process.cwd(), config.root)).toString();

	return root;
};

/**
 * Construct the meta given by the `bd-css.config.js` file.
 */
export const generateMeta = (meta: Config['meta']) => {
	return `/**\n${Object.entries(meta)
		.map(([key, value]) => ` * @${key} ${value}\n`)
		.join('')} */\n\n`;
};

export const writeToDisk = (name: string, file: string, dir: string) => {
	const dirPath = dir
		.split(sep)
		.filter((el) => !el.endsWith('.css'))
		.join(sep);

	// Check if path exists, if not make it.
	if (!existsSync(dirPath)) mkdirSync(dirPath, { recursive: true });

	// Write file to disk.
	try {
		writeFileSync(join(dirPath, name.replace(/ /g, '')), file);
	} catch (error) {
		log.error(error);
	}
};
